-- Arcanix core schema. Apply only with the approved local/CI Supabase workflow.
create extension if not exists pgcrypto;
create schema if not exists private;

create table public.games (id uuid primary key default gen_random_uuid(), slug text not null unique check(slug ~ '^[a-z0-9-]{2,60}$'), name text not null unique, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, handle text not null check(handle ~ '^[a-z0-9_]{3,30}$'), display_name text not null check(char_length(display_name) between 1 and 100), headline text, bio text, city text, country_code text check(country_code is null or country_code ~ '^[A-Z]{2}$'), is_discoverable boolean not null default true, is_suspended boolean not null default false, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index profiles_handle_lower_key on public.profiles(lower(handle));
create index profiles_discovery_idx on public.profiles(updated_at desc, id desc) where is_discoverable and not is_suspended and deleted_at is null;
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, role text not null check(role in ('player','recruiter','admin')), granted_by uuid references public.profiles(id) on delete set null, granted_at timestamptz not null default now(), revoked_by uuid references public.profiles(id) on delete set null, revoked_at timestamptz, revocation_reason text, note text);
create unique index user_roles_one_active_role_key on public.user_roles(user_id, role) where revoked_at is null;
create index user_roles_active_idx on public.user_roles(user_id, role) where revoked_at is null;
create table public.user_settings (profile_id uuid primary key references public.profiles(id) on delete cascade, profile_visibility text not null default 'public' check(profile_visibility in ('public','members','private')), allow_messages boolean not null default true, notify_email boolean not null default true, notify_push boolean not null default true, locale text not null default 'en-IN', created_at timestamptz not null default now(), updated_at timestamptz not null default now());

create table public.organizations (id uuid primary key default gen_random_uuid(), slug text not null, name text not null check(char_length(name) between 1 and 150), description text, region_code text, website_url text, created_by uuid not null references public.profiles(id) on delete restrict, verification_status text not null default 'unverified' check(verification_status in ('unverified','pending','verified','rejected')), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index organizations_slug_lower_key on public.organizations(lower(slug));
create table public.organization_members (organization_id uuid not null references public.organizations(id) on delete cascade, profile_id uuid not null references public.profiles(id) on delete cascade, membership_role text not null check(membership_role in ('owner','admin','recruiter','editor','member')), status text not null default 'invited' check(status in ('invited','active','removed')), granted_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(organization_id, profile_id));
create index organization_members_person_idx on public.organization_members(profile_id,status,organization_id);
create index organization_members_role_idx on public.organization_members(organization_id,membership_role) where status='active';

create table public.player_details (profile_id uuid primary key references public.profiles(id) on delete cascade, primary_game_id uuid references public.games(id) on delete set null, primary_role text, rank_label text, availability text not null default 'open' check(availability in ('open','limited','not_looking')), birth_year smallint, pronouns text, languages text[] not null default '{}', looking_for text[] not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.player_skills (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, game_id uuid not null references public.games(id) on delete restrict, role_name text not null, rank_label text, years_experience numeric(4,1) check(years_experience>=0), is_primary boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(profile_id,game_id,role_name));
create unique index player_skills_one_primary_key on public.player_skills(profile_id) where is_primary;
create index player_skills_discovery_idx on public.player_skills(game_id,role_name,rank_label,profile_id);
create table public.player_achievements (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, game_id uuid references public.games(id) on delete set null, title text not null, issuer text, achieved_on date, placement text, evidence_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.player_experience (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, organization_id uuid references public.organizations(id) on delete set null, team_name text, title text not null, game_id uuid references public.games(id) on delete set null, started_on date, ended_on date, is_current boolean not null default false, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(ended_on is null or started_on is null or ended_on>=started_on));
create table public.profile_media (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, bucket_id text not null check(bucket_id='profile-media'), storage_path text not null, media_kind text not null check(media_kind in ('image','video')), mime_type text not null, byte_size bigint not null check(byte_size>0), width integer, height integer, duration_ms integer, purpose text not null check(purpose in ('avatar','banner','highlight')), is_primary boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(bucket_id,storage_path), check((media_kind='image' and width>0 and height>0) or (media_kind='video' and duration_ms>0)));
create unique index profile_media_primary_purpose_key on public.profile_media(profile_id,purpose) where is_primary;

create table public.verification_requests (id uuid primary key default gen_random_uuid(), requested_by uuid not null references public.profiles(id) on delete restrict, subject_profile_id uuid references public.profiles(id) on delete cascade, subject_organization_id uuid references public.organizations(id) on delete restrict, verification_kind text not null check(verification_kind in ('player','recruiter','organization')), status text not null default 'pending' check(status in ('pending','approved','rejected','withdrawn')), submission_number integer not null default 1 check(submission_number>0), applicant_note text, reviewed_by uuid references public.profiles(id) on delete set null, reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check((verification_kind='organization' and subject_profile_id is null and subject_organization_id is not null) or (verification_kind in ('player','recruiter') and subject_profile_id is not null and subject_organization_id is null)));
create unique index verification_one_pending_profile_key on public.verification_requests(subject_profile_id,verification_kind) where status='pending' and subject_profile_id is not null;
create unique index verification_one_pending_org_key on public.verification_requests(subject_organization_id,verification_kind) where status='pending' and subject_organization_id is not null;
create table public.verification_history (id uuid primary key default gen_random_uuid(), request_id uuid not null references public.verification_requests(id) on delete restrict, action text not null check(action in ('submitted','resubmitted','approved','rejected','withdrawn','appeal_opened')), from_status text, to_status text, actor_id uuid references public.profiles(id) on delete set null, applicant_message text, created_at timestamptz not null default now());
create table public.verification_review_notes (id uuid primary key default gen_random_uuid(), request_id uuid not null references public.verification_requests(id) on delete restrict, author_id uuid references public.profiles(id) on delete set null, note text not null, created_at timestamptz not null default now());
create table public.verification_documents (id uuid primary key default gen_random_uuid(), request_id uuid not null references public.verification_requests(id) on delete cascade, bucket_id text not null check(bucket_id='verification-private'), storage_path text not null, document_type text not null, mime_type text not null, byte_size bigint not null check(byte_size>0), uploaded_by uuid not null references public.profiles(id) on delete restrict, created_at timestamptz not null default now(), unique(bucket_id,storage_path));

create table public.posts (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id) on delete cascade, organization_id uuid references public.organizations(id) on delete set null, body text not null check(char_length(body) between 1 and 5000), visibility text not null default 'public' check(visibility in ('public','connections','organization','private')), commenting text not null default 'everyone' check(commenting in ('everyone','connections','none')), is_pinned boolean not null default false, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index posts_author_feed_idx on public.posts(author_id,created_at desc,id desc) where deleted_at is null;
create index posts_public_feed_idx on public.posts(created_at desc,id desc) where deleted_at is null and visibility='public';
create table public.post_media (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, bucket_id text not null check(bucket_id='post-media'), storage_path text not null, media_kind text not null check(media_kind in ('image','video')), mime_type text not null, byte_size bigint not null check(byte_size>0), width integer, height integer, duration_ms integer, position smallint not null check(position between 0 and 9), alt_text text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(post_id,position), unique(bucket_id,storage_path), check((media_kind='image' and width>0 and height>0) or (media_kind='video' and duration_ms>0)));
create table public.likes (post_id uuid not null references public.posts(id) on delete cascade, profile_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(post_id,profile_id));
create table public.comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, author_id uuid not null references public.profiles(id) on delete cascade, parent_id uuid references public.comments(id) on delete set null, body text not null check(char_length(body) between 1 and 2000), deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.follows (follower_id uuid not null references public.profiles(id) on delete cascade, followed_id uuid not null references public.profiles(id) on delete cascade, created_at timestamptz not null default now(), primary key(follower_id,followed_id), check(follower_id<>followed_id));
create table public.connections (id uuid primary key default gen_random_uuid(), requester_id uuid not null references public.profiles(id) on delete cascade, recipient_id uuid not null references public.profiles(id) on delete cascade, status text not null default 'pending' check(status in ('pending','accepted','declined','blocked','cancelled')), responded_at timestamptz, blocked_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(requester_id<>recipient_id));
create unique index connections_unordered_pair_key on public.connections(least(requester_id,recipient_id),greatest(requester_id,recipient_id));
create table public.connection_events (id uuid primary key default gen_random_uuid(), connection_id uuid not null references public.connections(id) on delete cascade, actor_id uuid references public.profiles(id) on delete set null, action text not null check(action in ('requested','accepted','declined','cancelled','reopened','blocked','unblocked')), created_at timestamptz not null default now());
create table public.saved_posts (profile_id uuid not null references public.profiles(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, created_at timestamptz not null default now(), primary key(profile_id,post_id));

create table public.opportunities (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, created_by uuid not null references public.profiles(id) on delete restrict, game_id uuid references public.games(id) on delete set null, title text not null, description text not null, role_name text, location_type text not null default 'remote' check(location_type in ('remote','hybrid','on_site')), region_code text, status text not null default 'draft' check(status in ('draft','published','paused','closed')), openings smallint not null default 1 check(openings>0), closes_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index opportunities_discovery_idx on public.opportunities(game_id,created_at desc,id desc) where status='published';
create table public.applications (id uuid primary key default gen_random_uuid(), opportunity_id uuid not null references public.opportunities(id) on delete cascade, applicant_id uuid not null references public.profiles(id) on delete cascade, cover_note text, status text not null default 'submitted' check(status in ('submitted','under_review','interview','offered','rejected','withdrawn')), withdrawn_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(opportunity_id,applicant_id));
create table public.application_reviews (id uuid primary key default gen_random_uuid(), application_id uuid not null references public.applications(id) on delete cascade, reviewer_id uuid references public.profiles(id) on delete set null, from_status text, to_status text, internal_note text, created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), recipient_id uuid not null references public.profiles(id) on delete cascade, actor_id uuid references public.profiles(id) on delete set null, type text not null, payload jsonb not null default '{}'::jsonb, read_at timestamptz, created_at timestamptz not null default now());
create table public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id) on delete restrict, subject_profile_id uuid references public.profiles(id) on delete set null, subject_post_id uuid references public.posts(id) on delete set null, subject_comment_id uuid references public.comments(id) on delete set null, subject_opportunity_id uuid references public.opportunities(id) on delete set null, reason text not null, detail text, status text not null default 'open' check(status in ('open','investigating','resolved','dismissed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(num_nonnulls(subject_profile_id,subject_post_id,subject_comment_id,subject_opportunity_id)=1));
create table public.report_reviews (id uuid primary key default gen_random_uuid(), report_id uuid not null references public.reports(id) on delete cascade, reviewer_id uuid references public.profiles(id) on delete set null, from_status text, to_status text, internal_note text, created_at timestamptz not null default now());
create table public.admin_actions (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id) on delete set null, action_type text not null, target_profile_id uuid references public.profiles(id) on delete set null, target_organization_id uuid references public.organizations(id) on delete set null, target_verification_request_id uuid references public.verification_requests(id) on delete set null, target_report_id uuid references public.reports(id) on delete set null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), check(num_nonnulls(target_profile_id,target_organization_id,target_verification_request_id,target_report_id)<=1));

create or replace function private.set_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end; $$;
create or replace function private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,handle,display_name) values(new.id,'user_'||left(new.id::text,8),coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),'New player')); insert into public.user_settings(profile_id) values(new.id); insert into public.user_roles(user_id,role) values(new.id,'player'); return new; end; $$;
create or replace function private.create_organization_owner() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.organization_members(organization_id,profile_id,membership_role,status,granted_by) values(new.id,new.created_by,'owner','active',new.created_by); return new; end; $$;
revoke all on function private.handle_new_user() from public;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();
create trigger on_organization_created after insert on public.organizations for each row execute function private.create_organization_owner();
do $$ declare t text; begin foreach t in array array['profiles','user_settings','organizations','organization_members','player_details','player_skills','player_achievements','player_experience','profile_media','verification_requests','posts','post_media','comments','connections','opportunities','applications','reports'] loop execute format('create trigger %I before update on public.%I for each row execute function private.set_updated_at()',t||'_updated',t); end loop; end $$;
